package got.wildlife; import net.minecraft.world.entity.*; import net.minecraft.world.entity.ai.attributes.*; import net.minecraft.world.level.Level; public final class GOTWhiteOryxEntity extends GOTOryxEntity { public GOTWhiteOryxEntity(EntityType<? extends net.minecraft.world.entity.animal.Animal> t,Level l){super(t,l);} public static AttributeSupplier.Builder createWhiteAttributes(){return Mob.createMobAttributes().add(Attributes.MAX_HEALTH,16).add(Attributes.MOVEMENT_SPEED,.22).add(Attributes.ATTACK_DAMAGE,3).add(Attributes.FOLLOW_RANGE,18);} }